{
  "primary_meaning": "Light, righteousness, divine presence/truth, or the sphere of godly living (in explicit contrast to night as darkness, evil, or ignorance)",
  "primary_basis": [
    "1 Thessalonians 5:4-8",
    "Romans 13:12-13",
    "John 9:4; 11:9-10",
    "Ephesians 5:8",
    "Genesis 1:3-5"
  ],
  "alternatives": [
    {
      "meaning": "The eschatological 'Day of the Lord' as a climactic time of divine judgment and/or salvation",
      "basis": [
        "Isaiah 13:6,9",
        "Joel 2:1,11,31",
        "Amos 5:18-20",
        "Zephaniah 1:14-18",
        "1 Thessalonians 5:2",
        "2 Peter 3:10"
      ],
      "prominence": "dominant"
    },
    {
      "meaning": "A prophetic year (day-year principle of interpretation)",
      "basis": [
        "Numbers 14:34",
        "Ezekiel 4:6"
      ],
      "prominence": "common"
    },
    {
      "meaning": "A thousand years in divine reckoning",
      "basis": [
        "2 Peter 3:8",
        "Psalm 90:4"
      ],
      "prominence": "common"
    },
    {
      "meaning": "An indefinite age or long creative/era period (day-age readings of Genesis)",
      "basis": [
        "Genesis 1",
        "2 Peter 3:8"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": false,
  "confidence": "high",
  "notes": "Symbolic uses of 'day' are strongly context-dependent across Christian tradition and biblical studies; the light/righteousness contrast is the most basic and widespread single motif, while 'Day of the Lord,' day-year, and day=1000 years readings are frequent in specific genres (prophecy, eschatology, creation debates) without a single overarching consensus that covers every occurrence."
}
